# Red when: `install <file.json>` stops deriving the package name from the file, an ad-hoc install stops
# recording `<auto-generated>` as its source, a URL manifest stops being copied under `.coop/manifests`,
# or the installed ad-hoc package stops being uninstallable.
param([Parameter(Mandatory)][string]$CoopExe, [Parameter(Mandatory)][string]$TestRoot)
$ErrorActionPreference = 'Stop'
$TestRoot = [IO.Path]::GetFullPath($TestRoot)
$allowedRoot = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../.local/tests')).TrimEnd('\') + '\'
if (-not ($TestRoot.TrimEnd('\') + '\').StartsWith($allowedRoot, [StringComparison]::OrdinalIgnoreCase)) {
    throw 'Test data must stay within the project test directory'
}
$archive = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../.local/deps/test-archives/ripgrep-15.2.0-x86_64-pc-windows-msvc.zip'))
if (-not (Test-Path -LiteralPath $archive)) { throw "Missing test archive: $archive" }
$hash = (Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLower()
$url = 'file:///' + ($archive -replace '\\', '/')
$root = Join-Path $TestRoot 'adhoc'
if (Test-Path $root) { Remove-Item -LiteralPath $root -Recurse -Force }
New-Item -ItemType Directory -Path $root -Force | Out-Null
function Write-Manifest([string]$Path,[string]$Alias) {
    @"
{
  "version": "9.9",
  "url": "$url",
  "hash": "$hash",
  "extract_dir": "ripgrep-15.2.0-x86_64-pc-windows-msvc",
  "bin": [ [ "rg.exe", "$Alias" ] ]
}
"@ | Set-Content -LiteralPath $Path -Encoding utf8 -NoNewline
}

# A local manifest installs under its own file name and records the ad-hoc source.
$local = Join-Path $root 'from-file.json'
Write-Manifest $local 'rgfromfile'
$lines = @(& $CoopExe --root $root install $local)
if ($LASTEXITCODE -cne 0) { throw "installing a local manifest failed: $($lines -join ' | ')" }
$installed = @(& $CoopExe --root $root list)
if ($installed -join "`n" -cnotmatch 'from-file\s+9\.9\s+<auto-generated>') {
    throw "the ad-hoc install is not recorded as <auto-generated>: $($installed -join ' | ')"
}

# A URL manifest is copied under .coop/manifests and installed under the URL's file name.
$remote = Join-Path $root 'from-url.json'
Write-Manifest $remote 'rgfromurl'
$source = 'file:///' + ($remote -replace '\\', '/')
$lines = @(& $CoopExe --root $root install $source)
if ($LASTEXITCODE -cne 0) { throw "installing a URL manifest failed: $($lines -join ' | ')" }
$installed = @(& $CoopExe --root $root list)
if ($installed -join "`n" -cnotmatch 'from-url\s+9\.9\s+<auto-generated>') {
    throw "the URL install is not listed: $($installed -join ' | ')"
}
if (@(Get-ChildItem "$root/.coop/manifests" -File -ErrorAction SilentlyContinue).Count -cne 1) {
    throw 'the URL manifest was not copied under .coop/manifests'
}

# Both ad-hoc packages uninstall like any other.
foreach ($name in 'from-file','from-url') {
    $lines = @(& $CoopExe --root $root uninstall $name)
    if ($LASTEXITCODE -cne 0) { throw "uninstalling $name failed: $($lines -join ' | ')" }
}
$installed = @(& $CoopExe --root $root list)
if (($installed -join "`n") -cnotmatch "There aren't any apps installed") { throw 'an ad-hoc package survived uninstall' }
Write-Output 'PASS: install from a local manifest and from a URL manifest'
